export const controlClasses={UA:{label:'Control ucraniano estimado',color:'#2478bd'},RU:{label:'Control ruso estimado',color:'#c2484d'},CONTESTED:{label:'En disputa',color:'#d79b21'},GAZA_ISRAEL:{label:'Control israelí estimado',color:'#2478bd'},GAZA_PALESTINIAN:{label:'Control palestino estimado',color:'#ba6266'},SAF:{label:'Fuerzas Armadas de Sudán · SAF',color:'#2478bd'},RSF:{label:'Fuerzas de Apoyo Rápido · RSF',color:'#c2484d'},SPLMN:{label:'SPLM-N (al-Hilu)',color:'#b08b16'},RSF_SPLMN:{label:'RSF y SPLM-N aliados',color:'#cf762d'},SLMAW:{label:'SLM (al-Nur)',color:'#85409e'},FARDC:{label:'FARDC · Gobierno de RD Congo',color:'#2478bd'},M23:{label:'M23 y aliados',color:'#c2484d'},UGANDA_PRESENCE:{label:'Presencia ugandesa',color:'#b08b16'},BURUNDI_PRESENCE:{label:'Presencia de Burundi',color:'#298553'},WAZALENDO_PRESENCE:{label:'Presencia Wazalendo',color:'#8f6c50'},UNKNOWN:{label:'Sin determinar',color:'#7b8790'}};
export function validateControl(data){
 if(data?.type!=='FeatureCollection'||!Array.isArray(data.features)||!data.features.length||!/^\d{4}-\d{2}-\d{2}$/.test(data.metadata?.date)||!Number.isFinite(Date.parse(data.metadata.date))||Date.parse(data.metadata.date)>Date.now()+86400000)throw Error('Datos de control territorial inválidos.');
 for(const f of data.features){if(!controlClasses[f.properties?.status]||!['Polygon','MultiPolygon'].includes(f.geometry?.type)||f.properties.date!==data.metadata.date)throw Error('Categoría o geometría no reconocida.');const rings=f.geometry.type==='Polygon'?f.geometry.coordinates:f.geometry.coordinates.flat();if(!rings.length||rings.some(r=>r.length<4||(r[0][0]!==r.at(-1)[0]||r[0][1]!==r.at(-1)[1])||r.some(p=>p.length<2||!Number.isFinite(p[0])||!Number.isFinite(p[1])||p[0]<-180||p[0]>180||p[1]<-90||p[1]>90)))throw Error('Coordenadas inválidas.');}
 return data;
}
export function controlAge(date,now=Date.now()){return Math.max(0,Math.floor((now-Date.parse(date+'T00:00:00Z'))/86400000));}
export const territoryLayers={ukraine:{label:'Ucrania',url:'/data/ukraine-control.geojson',bounds:[[44.2,22.1],[52.5,40.3]]},gaza:{label:'Gaza',url:'/data/gaza-control.geojson',bounds:[[31.20,34.20],[31.61,34.58]]},sudan:{label:'Sudán',url:'/data/sudan-control.geojson',bounds:[[9.4,21.7],[22.1,38.7]]},congo:{label:'Kivu · RD Congo',url:'/data/congo-control.geojson',bounds:[[-3.9,26.5],[.8,30.1]]}};
const escapeText=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeSource=u=>{try{const url=new URL(u);return url.protocol==='https:'?url.href:'#'}catch{return '#'}};
export function initConflictLayer({map,L,markers}){
 const host=document.querySelector('#panorama .panorama-grid');if(!host||!map||!L)return;
 const panel=document.createElement('section');panel.className='conflict-panel';panel.setAttribute('aria-label','Control territorial');
 panel.innerHTML=`<div class="conflict-heading"><label class="conflict-toggle"><input type="checkbox" id="conflict-enabled"> Áreas por bando</label><span id="conflict-name"></span></div><div id="conflict-options" hidden><div class="conflict-tools"><button id="conflict-focus">Centrar áreas</button><label>Opacidad <input id="conflict-opacity" type="range" min="15" max="80" value="45" aria-label="Opacidad de control territorial"></label><label><input type="checkbox" id="conflict-signals" checked> Mostrar noticias y señales</label></div><div class="conflict-legend" role="group" aria-label="Categorías de control territorial"></div><p id="conflict-status" role="status"></p><p id="conflict-coverage"></p><details><summary>Fuente, fecha y método</summary><div id="conflict-method"></div></details><button id="conflict-retry" hidden>Reintentar carga</button></div>`;host.before(panel);
 const stamp=document.createElement('span');stamp.id='territory-stamp';stamp.hidden=true;document.querySelector('.map-center .map-footer')?.append(stamp);
 const $=id=>panel.querySelector('#'+id),groups=new Map(),cache=new Map();let key='ukraine',data=null,requestId=0,abort=null;
 const renderer=L.canvas({padding:.3});
 function clear(){for(const group of groups.values())map.removeLayer(group);groups.clear();}
 function paint(){const enabled=$('conflict-enabled').checked;for(const [status,group] of groups){if(enabled&&panel.querySelector(`[data-control="${status}"]`)?.checked)group.addTo(map);else map.removeLayer(group);}stamp.hidden=!enabled||!data;}
 function status(){const m=data.metadata,age=controlAge(m.date);const text=`${territoryLayers[key].label} · corte ${m.date} · ${age>90?'Instantánea histórica':age>3?'Instantánea fechada':'Estimación'} · ${m.source||'VIINA 2.0'}`;$('conflict-status').textContent=text;stamp.textContent='Áreas: '+text;}
 function show(candidate){clear();data=candidate;const m=data.metadata,classes=[...new Set(data.features.map(f=>f.properties.status))];
  panel.querySelector('.conflict-legend').innerHTML=classes.map(c=>`<label><input type="checkbox" data-control="${c}" checked><span style="background:${controlClasses[c].color}" aria-hidden="true"></span>${controlClasses[c].label}</label>`).join('');
  $('conflict-coverage').textContent=m.coverage||'Cobertura: Ucrania. Zonas estimadas por localidades; no una línea de frente exacta.';
  $('conflict-method').innerHTML=`<p>${escapeText(m.method||'VIINA 2.0 · Yuri Zhukov y Natalie Ayers. Celdas de localidades agrupadas por clasificación. No se deduce control ucraniano por ausencia de control ruso.')}</p><p>${escapeText(m.accuracy||'Las áreas sin colorear no tienen clasificación en esta capa.')}</p><p><a href="${escapeText(safeSource(m.sourceUrl))}" target="_blank" rel="noopener noreferrer">${escapeText(m.source||'VIINA 2.0')} ↗</a> · <a href="${territoryLayers[key].url}" download>Descargar polígonos</a> · <a href="${escapeText(safeSource(m.licenseUrl||'https://opendatacommons.org/licenses/odbl/1-0/'))}" target="_blank" rel="noopener noreferrer">${escapeText(m.license)}</a></p>${m.baseSourceUrl?`<p>Base cartográfica: <a href="${escapeText(safeSource(m.baseSourceUrl))}" target="_blank" rel="noopener noreferrer">NordNordWest</a> · <a href="${escapeText(safeSource(m.baseLicenseUrl))}" target="_blank" rel="noopener noreferrer">CC BY-SA 3.0 DE</a></p>`:''}<p>${escapeText(m.sourceRevision?'Revisión del archivo: '+m.sourceRevision:'La fecha corresponde a los datos, no a la descarga.')}</p><p>${escapeText(m.updatePolicy||'Atlas comprueba la fuente cada 6 horas y conserva la última versión válida si falla la actualización. No es tiempo real.')}</p>`;
  for(const c of classes){const cls=controlClasses[c],presence=c.endsWith('_PRESENCE');const layer=L.geoJSON({type:'FeatureCollection',features:data.features.filter(f=>f.properties.status===c)},{renderer,style:{color:cls.color,weight:presence?2:1,fillColor:cls.color,fillOpacity:Number($('conflict-opacity').value)/100*(presence?.5:1),dashArray:presence||c==='CONTESTED'?'5 5':null},onEachFeature:(f,l)=>{const popup=document.createElement('div');popup.className='territory-popup';const title=document.createElement('strong');title.textContent=cls.label;const p=document.createElement('p');p.textContent=`${territoryLayers[key].label} · corte ${m.date}. ${f.properties.meaning||'Estimación por localidades; límite aproximado.'}`;const note=document.createElement('p');note.textContent=m.accuracy||'Límite aproximado.';const a=document.createElement('a');a.href=safeSource(m.sourceUrl);a.target='_blank';a.rel='noopener noreferrer';a.textContent=m.source||'VIINA 2.0';popup.append(title,p,note,a);l.bindPopup(popup);}});groups.set(c,layer);}
  panel.querySelectorAll('[data-control]').forEach(c=>c.onchange=paint);status();paint();
 }
 async function load(){const current=key,id=++requestId;abort?.abort();abort=new AbortController();const controller=abort;$('conflict-retry').hidden=true;if(!data)$('conflict-status').textContent='Cargando áreas por bando…';const timeout=setTimeout(()=>controller.abort(),25000);
  try{const r=await fetch(territoryLayers[current].url,{cache:'no-cache',signal:controller.signal});if(!r.ok)throw Error();const candidate=validateControl(await r.json());if(current!=='ukraine'&&candidate.metadata.conflict!==current)throw Error('Conflicto incorrecto');if(cache.has(current)&&candidate.metadata.date<cache.get(current).metadata.date)throw Error('Fecha regresiva');if(id!==requestId||current!==key)return;cache.set(current,candidate);show(candidate);
  }catch{if(id!==requestId||current!==key)return;$('conflict-status').textContent=data?`No se pudo actualizar. Conservamos el corte ${data.metadata.date}.`:'No se pudo cargar esta capa. Reintenta.';$('conflict-retry').hidden=false;}finally{clearTimeout(timeout);}
 }
 function setEnabled(enabled){$('conflict-enabled').checked=enabled;$('conflict-options').hidden=!enabled;if(enabled){if(data)paint();else load();}else{paint();if(markers&&!map.hasLayer(markers))markers.addTo(map);}}
 $('conflict-enabled').onchange=()=>setEnabled($('conflict-enabled').checked);$('conflict-focus').onclick=()=>{map.invalidateSize();map.fitBounds(territoryLayers[key].bounds,{padding:[15,15]});};
 $('conflict-opacity').oninput=e=>{for(const [c,g] of groups)g.setStyle({fillOpacity:Number(e.target.value)/100*(c.endsWith('_PRESENCE')?.5:1)});};
 $('conflict-signals').onchange=e=>{if(markers){if(e.target.checked)markers.addTo(map);else map.removeLayer(markers);}};$('conflict-retry').onclick=load;
 setInterval(()=>{if(!document.hidden&&$('conflict-enabled').checked)load()},300000);
 function setConflict(next){if(!territoryLayers[next]){setEnabled(false);panel.hidden=true;return;}panel.hidden=false;if(next!==key){requestId++;abort?.abort();clear();key=next;data=null;$('conflict-status').textContent='';panel.querySelector('.conflict-legend').innerHTML='';$('conflict-coverage').textContent='';$('conflict-method').textContent='';if(cache.has(key))show(cache.get(key));}$('conflict-name').textContent=territoryLayers[key].label;setEnabled(true);}
 return {panel,setEnabled,setConflict};
}
